🚀 Demostración en Vivo🔬 Arenero de Exploración de Memoria (RAM) <pre><code>class ToolRegistryDemo:
    def __init__(self):
        self.tools = {}

    def register(self, name, fn):
        self.tools[name] = fn

    def run(self, name, **kwargs):
        return self.tools[name](**kwargs)

reg = ToolRegistryDemo()
reg.register("multiplicar", lambda x, y: x * y)
print("Resultado Tool Call:", reg.run("multiplicar", x=6, y=7))
